INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist eine Risikoanalyse immer notwendig, um ein IT-Projekt erfolgreich abzuschließen?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig vom Projektumfang, nicht immer zwingend"}, {"text": "Ja", "correct": false, "because": "Erforderlichkeit hängt vom Risikograd ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Risikoanalyse alle potenziellen Probleme eines Projekts vollständig eliminieren?', 2, '[{"text": "Nein", "correct": true, "because": "Sie identifiziert Risiken, behebt sie aber nicht"}, {"text": "Ja", "correct": false, "because": "Unvorhersehbare Faktoren bleiben"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei einer Risikoanalyse nur technische Risiken berücksichtigt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Auch organisatorische und rechtliche Risiken zählen"}, {"text": "Ja", "correct": false, "because": "Risiken sind vielfältig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine Risikoanalyse nur in der Anfangsphase eines Projekts relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Risiken ändern sich über den Projektverlauf"}, {"text": "Ja", "correct": false, "because": "Kontinuierliche Analyse ist nützlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Risiken in einer Risikoanalyse ohne quantitativen Ansatz bewertet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Qualitative Bewertungen sind ebenfalls effektiv"}, {"text": "Nein", "correct": false, "because": "Quantifizierung ist nicht zwingend"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt ist bei einer Risikoanalyse am wichtigsten, um geeignete Maßnahmen zu entwickeln?', 3, '[{"text": "Bewertung der Risiken", "correct": true, "because": "Priorisiert Maßnahmen nach Schwere"}, {"text": "Dokumentation der Risiken", "correct": false, "because": "Wichtig, aber nachgelagert"}, {"text": "Analyse historischer Daten", "correct": false, "because": "Hilfreich, aber nicht zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium wird primär genutzt, um die Dringlichkeit eines Risikos zu bestimmen?', 2, '[{"text": "Wahrscheinlichkeit und Auswirkung", "correct": true, "because": "Kombiniert Eintritt und Schaden"}, {"text": "Kosten der Vermeidung", "correct": false, "because": "Sekundär zur Bewertung"}, {"text": "Technische Komplexität", "correct": false, "because": "Nicht primäres Kriterium"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode ist am effektivsten, um unbekannte Risiken in einem Projekt zu identifizieren?', 3, '[{"text": "Brainstorming mit Experten", "correct": true, "because": "Nutzt vielfältige Perspektiven"}, {"text": "Automatische Risikosuche", "correct": false, "because": "Fehlt Kontext"}, {"text": "Vergleich mit Markttrends", "correct": false, "because": "Extern, nicht projektspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann eine Risikoanalyse am stärksten unbrauchbar machen?', 2, '[{"text": "Unrealistische Annahmen", "correct": true, "because": "Verzerrt Bewertung und Maßnahmen"}, {"text": "Zu detaillierte Dokumentation", "correct": false, "because": "Detailtiefe schadet nicht"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Geschwindigkeit ist sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel einer Risikoanalyse in einem IT-Projekt?', 3, '[{"text": "Minimierung von Unsicherheiten", "correct": true, "because": "Identifiziert und priorisiert Risiken"}, {"text": "Maximierung der Funktionalität", "correct": false, "because": "Technisches Ziel"}, {"text": "Reduktion der Entwicklungszeit", "correct": false, "because": "Nebenaspekt"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Risiken sollten in einer Risikoanalyse für ein IT-Projekt berücksichtigt werden?', 4, '[{"text": "Technische Ausfälle", "correct": true, "because": "Beeinträchtigen Systeme"}, {"text": "Budgetüberschreitungen", "correct": true, "because": "Wirtschaftliches Risiko"}, {"text": "Maximale Nutzerzahl", "correct": false, "because": "Kein Risiko, sondern Faktor"}, {"text": "Rechtliche Verstöße", "correct": true, "because": "Können Projekt stoppen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind essenziell für eine effektive Risikoanalyse?', 3, '[{"text": "Risikoidentifikation", "correct": true, "because": "Erster Schritt zur Erkennung"}, {"text": "Risikobewertung", "correct": true, "because": "Priorisiert Gefahren"}, {"text": "Festlegung der Programmiersprache", "correct": false, "because": "Nicht Teil der Analyse"}, {"text": "Maßnahmenplanung", "correct": true, "because": "Reduziert Risiken"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen können bei einer Risikoanalyse auftreten?', 4, '[{"text": "Unvollständige Informationen", "correct": true, "because": "Erschwert Identifikation"}, {"text": "Subjektive Einschätzungen", "correct": true, "because": "Verzerren Bewertungen"}, {"text": "Schnelle Berechnung", "correct": false, "because": "Kein Hindernis"}, {"text": "Unvorhersehbare externe Faktoren", "correct": true, "because": "Beeinflussen Prognosen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gründliche Risikoanalyse?', 3, '[{"text": "Frühwarnsystem für Probleme", "correct": true, "because": "Erkennt Gefahren früh"}, {"text": "Bessere Ressourcenplanung", "correct": true, "because": "Antizipiert Bedarf"}, {"text": "Automatische Fehlerbehebung", "correct": false, "because": "Analyse behebt nicht"}, {"text": "Reduzierte Projektverzögerungen", "correct": true, "because": "Vermeidet Stolpersteine"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden können zur Risikoanalyse eingesetzt werden?', 3, '[{"text": "SWOT-Analyse", "correct": true, "because": "Identifiziert Stärken und Schwächen"}, {"text": "FMEA (Fehlermöglichkeits- und Einflussanalyse)", "correct": true, "because": "Detailierte Risikobetrachtung"}, {"text": "Code-Optimierung", "correct": false, "because": "Technische Maßnahme"}, {"text": "Checklisten", "correct": true, "because": "Systematische Erfassung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Eine Risikoanalyse sollte nur am Projektstart erfolgen. b) Sie kann Kostenüberschreitungen vorbeugen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Analyse ist fortlaufend, Kostenrisiken werden reduziert"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Risikoanalyse kann ohne Stakeholder-Beteiligung durchgeführt werden. b) Sie hilft, Prioritäten im Projekt zu setzen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Stakeholder verbessern Analyse, Prioritäten werden klar"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist nicht ideal"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine Risikoanalyse garantiert den Projekterfolg. b) Sie sollte regelmäßig aktualisiert werden.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Erfolg ist nicht garantiert, Aktualisierung ist nötig"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Risiken müssen immer quantifiziert werden, um bewertet zu werden. b) Eine Risikoanalyse kann die Entscheidungsfindung unterstützen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Quantifizierung ist optional, Entscheidungen profitieren"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine Risikoanalyse ist nur für große Projekte sinnvoll. b) Sie kann technische und organisatorische Risiken abdecken.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Relevanz ist unabhängig von Größe, Risiken sind vielfältig"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

